  }
}
ORDER BY ?claimNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolderId ?premiumAmountPaid
       ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?coverage .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premium .

    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:hasPolicyHolder ?policyHolder .

    ?policyHolder a in:PolicyHolder ;
                  in:policyHolderId ?policyHolderId .

    ?premium a in:Premium ;
             in:premiumAmount ?premiumAmountPaid .

    OPTIONAL {
      ?claim in:hasLossPayment ?lossPayment .
      ?lossPayment a in:LossPayment ;
                   in:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lossReserve .
      ?lossReserve a in:LossReserve ;
                   in:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?expensePayment .
      ?expensePayment a in:ExpensePayment ;
                      in:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?expenseReserve .
      ?expenseReserve a in:ExpenseReserve ;
                      in:expenseReserveAmount ?expenseReserveAmount .
    }
  }
}
ORDER BY ?claimNumber ?policyNumber ?policyHolderId

PREFIX in: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?policyNumber ?numberOfClaims ?averageLoss
WHERE {
  SERVICE <mapped> {
    {
      SELECT ?policyNumber (COUNT(DISTINCT ?claim) AS ?numberOfClaims) (AVG(?claimLoss) AS ?averageLoss)
      WHERE {
        ?claim a in:Claim ;
               in:against ?pcd .

        ?pcd in:hasPolicy ?policy .
        ?policy in:policyNumber ?policyNumber .

        {
          SELECT ?claim
                 (COALESCE(SUM(DISTINCT xsd:decimal(?lpAmt)), 0) AS ?sumLossPayment)
                 (COALESCE(SUM(DISTINCT xsd:decimal(?lrAmt)), 0) AS ?sumLossReserve)
                 (COALESCE(SUM(DISTINCT xsd:decimal(?epAmt)), 0) AS ?sumExpensePayment)
                 (COALESCE(SUM(DISTINCT xsd:decimal(?erAmt)), 0) AS ?sumExpenseReserve)
                 ((COALESCE(SUM(DISTINCT xsd:decimal(?lpAmt)), 0) +
                   COALESCE(SUM(DISTINCT xsd:decimal(?lrAmt)), 0) +
                   COALESCE(SUM(DISTINCT xsd:decimal(?epAmt)), 0) +
                   COALESCE(SUM(DISTINCT xsd:decimal(?erAmt)), 0)) AS ?claimLoss)
          WHERE {
            OPTIONAL {
              ?claim in:hasLossPayment ?lp .
              ?lp in:lossPaymentAmount ?lpAmt .
            }
            OPTIONAL {
              ?claim in:hasLossReserve ?lr .
              ?lr in:lossReserveAmount ?lrAmt .
            }
            OPTIONAL {
              ?claim in:hasExpensePayment ?ep .
              ?ep in:expensePaymentAmount ?epAmt .
            }
            OPTIONAL {
              ?claim in:hasExpenseReserve ?er .
              ?er in:expenseReserveAmount ?erAmt .
            }
          }
          GROUP BY ?claim
        }
      }
      GROUP BY ?policyNumber
    }
  }
}
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?lossReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:hasLossReserve ?lossReserve .
    ?lossReserve in:lossReserveAmount ?lossReserveAmount .
  }
}
ORDER BY ?claimNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId ?policy ?policyNumber
       (COALESCE(?sumLossPayment, 0) + COALESCE(?sumLossReserve, 0) + COALESCE(?sumExpensePayment, 0) + COALESCE(?sumExpenseReserve, 0) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:soldByAgent ?agent ;
            in:policyNumber ?policyNumber .

    ?agent in:agentId ?agentId .

    {
      SELECT ?policy (SUM(?lpAmt) AS ?sumLossPayment)
      WHERE {
        ?pcd in:hasPolicy ?policy .
        ?claim in:against ?pcd ;
               in:hasLossPayment ?lp .
        ?lp in:lossPaymentAmount ?lpAmt .
      }
      GROUP BY ?policy
    }

    OPTIONAL {
      SELECT ?policy (SUM(?lrAmt) AS ?sumLossReserve)
      WHERE {
        ?pcd in:hasPolicy ?policy .
        ?claim in:against ?pcd ;
               in:hasLossReserve ?lr .
        ?lr in:lossReserveAmount ?lrAmt .
      }
      GROUP BY ?policy
    }

    OPTIONAL {
      SELECT ?policy (SUM(?epAmt) AS ?sumExpensePayment)
      WHERE {
        ?pcd in:hasPolicy ?policy .
        ?claim in:against ?pcd ;
               in:hasExpensePayment ?ep .
        ?ep in:expensePaymentAmount ?epAmt .
      }
      GROUP BY ?policy
    }

    OPTIONAL {
      SELECT ?policy (SUM(?erAmt) AS ?sumExpenseReserve)
      WHERE {
        ?pcd in:hasPolicy ?policy .
        ?claim in:against ?pcd ;
               in:hasExpenseReserve ?er .
        ?er in:expenseReserveAmount ?erAmt .
      }
      GROUP BY ?policy
    }
  }
}
ORDER BY ?agentId ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?claimNumber ?catastropheName ?policyNumber
       (SUM(?lossPaymentVal) AS ?totalLossPayment)
       (SUM(?lossReserveVal) AS ?totalLossReserve)
       (SUM(?expensePaymentVal) AS ?totalExpensePayment)
       (SUM(?expenseReserveVal) AS ?totalExpenseReserve)
       ((SUM(?lossPaymentVal) + SUM(?lossReserveVal) + SUM(?expensePaymentVal) + SUM(?expenseReserveVal)) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?coverage .

    OPTIONAL {
      ?claim in:hasCatastrophe ?cat .
      ?cat in:catastropheName ?catastropheName .
    }

    ?coverage in:hasPolicy ?policy .
    ?policy in:policyNumber ?policyNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lpAmt .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lrAmt .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?epAmt .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?erAmt .
    }

    BIND(COALESCE(xsd:decimal(?lpAmt), 0) AS ?lossPaymentVal)
    BIND(COALESCE(xsd:decimal(?lrAmt), 0) AS ?lossReserveVal)
    BIND(COALESCE(xsd:decimal(?epAmt), 0) AS ?expensePaymentVal)
    BIND(COALESCE(xsd:decimal(?erAmt), 0) AS ?expenseReserveVal)
  }
}
GROUP BY ?claimNumber ?catastropheName ?policyNumber
ORDER BY ?claimNumber ?catastropheName ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT (COUNT(DISTINCT ?claim) AS ?claimCount)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim .
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?lossPaymentAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:hasLossPayment ?lossPayment .
    ?lossPayment in:lossPaymentAmount ?lossPaymentAmount .
  }
}
ORDER BY ?claimNumber
